func carres(n int) <-chan int {
    c := make(chan int)
    go func() {
        defer close(c)
        for i := 1; i <= n; i++ {
            c <- i * i
        }
    }()
    return c
}
s := 0
for v := range carres(3) {
    s += v
}
fmt.Println(s)

